### 6.2 Linear Blending Implementation

```rust
pub struct LinearBlender;

impl TrajectoryBlenderTrait for LinearBlender {
    fn blend(
        &self,
        current_queue: &[PrioritizedAction],
        new_trajectory: &[PrioritizedAction],
        config: &BlendConfig,
    ) -> Vec<PrioritizedAction> {
        if current_queue.is_empty() {
            return new_trajectory.to_vec();
        }

        let blend_steps = (config.blend_duration_ms as f32 / 20.0) as usize; // 50Hz
        let mut result = Vec::new();

        // Take first few from current queue for blending
        let current_end = current_queue.first().unwrap();
        let new_start = new_trajectory.first().unwrap();

        // Generate blend trajectory
        for i in 0..blend_steps {
            let alpha = i as f32 / blend_steps as f32;
            let blended_dof: Vec<f32> = current_end
                .dof
                .iter()
                .zip(new_start.dof.iter())
                .map(|(a, b)| a * (1.0 - alpha) + b * alpha)
                .collect();

            result.push(PrioritizedAction {
                timestamp_unix_ns: current_end.timestamp_unix_ns
                    + (i as u64 * 20_000_000), // 20ms per step
                dof: blended_dof,
                priority: new_trajectory.first().unwrap().priority,
                source: ActionSource {
                    source_type: ActionSourceType::Blend,
                    source_id: "blend".to_string(),
                    created_at_unix_ns: current_end.timestamp_unix_ns,
                    ..Default::default()
                },
                sequence_idx: i,
                total_in_sequence: blend_steps + new_trajectory.len(),
                deadline_unix_ns: None,
            });
        }

        // Append new trajectory after blend
        result.extend(new_trajectory.iter().cloned());

        result
    }
}
```

