## 7. Integration with Supervisor

### 7.1 Modified Supervisor Runtime

```rust
pub struct SupervisorRuntime {
    // Replace VecDeque with priority queue
    action_queue: PriorityActionQueue,
    blender: Box<dyn TrajectoryBlenderTrait>,

    // ... other fields
}

impl SupervisorRuntime {
    fn stitch_with_priority(
        &mut self,
        traj: Trajectory,
        priority: u8,
        source: ActionSource,
    ) -> Result<()> {
        // Evaluate preemption
        let decision = self.action_queue.evaluate_preemption(priority);

        match decision {
            PreemptionDecision::Accept => {
                // Add to queue normally
                self.inject_trajectory(traj, priority, source)?;
            }
            PreemptionDecision::Preempt { cleared } => {
                // Clear and blend
                self.action_queue.on_preemption(priority);

                // Generate blended trajectory
                let current = self.action_queue.snapshot_actions();
                let new_actions = self.create_prioritized_actions(traj, priority, source);
                let blended = self.blender.blend(¤t, &new_actions, &self.blend_config);

                // Inject blended trajectory
                for action in blended {
                    self.action_queue.push(action)?;
                }

                counter_inc("preemptions_total", 1);
                gauge_set("actions_cleared_on_preempt", cleared as f64);
            }
            PreemptionDecision::Reject { reason } => {
                // Log and ignore
                log::debug!("Trajectory rejected: {}", reason);
            }
        }

        Ok(())
    }

    fn apply_safety_and_advance_queue(&mut self, now_ns: u64) -> Result<()> {
        let Some(next_action) = self.action_queue.peek().cloned() else {
            return Ok(());
        };

        // Check deadline
        if let Some(deadline) = next_action.deadline_unix_ns {
            if now_ns > deadline {
                // Action expired
                self.action_queue.pop();
                counter_inc("actions_expired_total", 1);
                return self.apply_safety_and_advance_queue(now_ns);
            }
        }

        let decision = {
            let arb = self.safety.lock().unwrap();
            arb.decide(now_ns, &next_action.into())
        };

        match decision {
            SafetyDecision::Allow => {
                let completed = self.action_queue.pop().unwrap();
                self.action_queue.on_action_completed(&completed);
            }
            SafetyDecision::Clamp { .. } => {
                let completed = self.action_queue.pop().unwrap();
                self.action_queue.on_action_completed(&completed);
            }
            SafetyDecision::Halt { reason } => {
                let cleared = self.action_queue.clear();
                self.emit_error(&self.active_ids().0, &self.active_ids().1,
                    format!("safety_halt: {} (cleared {} actions)", reason, cleared))?;
            }
        }

        Ok(())
    }
}
```

