import asyncio
from pathlib import Path
from typing import AsyncIterator

class LogStreamer:
    """Stream logs in real-time."""

    @staticmethod
    async def tail_file(file_path: Path, lines: int = 100) -> AsyncIterator[str]:
        """Tail a file and yield new lines."""
        with open(file_path, 'r') as f:
            # Get last N lines
            f.seek(0, 2)  # End of file
            size = f.tell()
            f.seek(max(0, size - 10000))  # Last ~10KB
            initial_lines = f.readlines()[-lines:]

            for line in initial_lines:
                yield line

            # Stream new lines
            while True:
                line = f.readline()
                if line:
                    yield line
                else:
                    await asyncio.sleep(0.1)
