    def pause_experiment(self, experiment_id: str) -> bool:
        """Pause any experiment."""
        if experiment_id not in self.processes:
            return False

        process = self.processes[experiment_id]
        try:
            psutil.Process(process.pid).suspend()
            self.active_experiments[experiment_id].status = ExperimentStatus.PAUSED
            return True
        except psutil.NoSuchProcess:
            return False

    def resume_experiment(self, experiment_id: str) -> bool:
        """Resume any experiment."""
        if experiment_id not in self.processes:
            return False

        process = self.processes[experiment_id]
        try:
            psutil.Process(process.pid).resume()
            self.active_experiments[experiment_id].status = ExperimentStatus.RUNNING
            return True
        except psutil.NoSuchProcess:
            return False

    def stop_experiment(self, experiment_id: str) -> bool:
        """Stop any experiment."""
        if experiment_id not in self.processes:
            return False

        process = self.processes[experiment_id]
        process.terminate()
        process.wait(timeout=30)

        self.active_experiments[experiment_id].status = ExperimentStatus.CANCELLED
        return True

    def list_experiments(self, workflow_type: Optional[WorkflowType] = None):
        """List all experiments."""
        experiments = list(self.active_experiments.values())

        if workflow_type:
            experiments = [e for e in experiments if e.workflow_type == workflow_type]

        return experiments
