from fastapi import APIRouter, HTTPException
from typing import Optional
from ..services.experiment_manager import ExperimentManager
from ..models.experiment import WorkflowType

router = APIRouter()
manager = ExperimentManager()

@router.post("/vea/start")
async def start_vea(
    name: str,
    config_path: str,
    stage: int,
    gpu_ids: list[int]
):
    """Start VEA training."""
    experiment = manager.start_vea_training(name, config_path, stage, gpu_ids)
    return experiment.dict()

@router.post("/expert/start")
async def start_expert(
    name: str,
    architecture: str,
    config_path: str,
    gpu_ids: list[int]
):
    """Start expert training."""
    experiment = manager.start_expert_training(name, architecture, config_path, gpu_ids)
    return experiment.dict()

@router.get("/")
async def list_experiments(workflow_type: Optional[str] = None):
    """List all experiments."""
    wf_type = WorkflowType(workflow_type) if workflow_type else None
    experiments = manager.list_experiments(wf_type)
    return [e.dict() for e in experiments]

@router.post("/{experiment_id}/pause")
async def pause(experiment_id: str):
    """Pause experiment."""
    success = manager.pause_experiment(experiment_id)
    if not success:
        raise HTTPException(status_code=404, detail="Experiment not found")
    return {"status": "paused"}

@router.post("/{experiment_id}/resume")
async def resume(experiment_id: str):
    """Resume experiment."""
    success = manager.resume_experiment(experiment_id)
    if not success:
        raise HTTPException(status_code=404, detail="Experiment not found")
    return {"status": "resumed"}

@router.post("/{experiment_id}/stop")
async def stop(experiment_id: str):
    """Stop experiment."""
    success = manager.stop_experiment(experiment_id)
    if not success:
        raise HTTPException(status_code=404, detail="Experiment not found")
    return {"status": "stopped"}
