  }

  getStatusIcon(): string {
    const icons = { running: 'play_circle', paused: 'pause_circle', completed: 'check_circle', failed: 'error' };
    return icons[this.experiment.status];
  }

  onPause() { this.pause.emit(this.experiment.experiment_id); }
  onResume() { this.resume.emit(this.experiment.experiment_id); }
  onStop() { this.stop.emit(this.experiment.experiment_id); }
}
