```typescript
@Injectable({providedIn: 'root'})
export class AITunerService {
  private apiUrl = '/api/v1';

  // Launch tuning job
  launchTuning(config: TunerConfig): Observable<LaunchResponse> {
    return this.http.post<LaunchResponse>(`${this.apiUrl}/launch`, {
      workflow_type: 'ai_tuner',
      operation: 'run',
      config: config
    });
  }

  // Get tuning status
  getTuningStatus(experimentId: string): Observable<TuningStatus> {
    return this.http.get<TuningStatus>(`${this.apiUrl}/experiments/${experimentId}`);
  }

  // Get iteration history
  getIterations(experimentId: string): Observable<Iteration[]> {
    return this.http.get<Iteration[]>(`${this.apiUrl}/experiments/${experimentId}/iterations`);
  }

  // Stop tuning
  stopTuning(experimentId: string): Observable<void> {
    return this.http.post<void>(`${this.apiUrl}/experiments/${experimentId}/stop`, {});
  }

  // Pause tuning
  pauseTuning(experimentId: string): Observable<void> {
    return this.http.post<void>(`${this.apiUrl}/experiments/${experimentId}/pause`, {});
  }

  // Resume tuning
  resumeTuning(experimentId: string): Observable<void> {
    return this.http.post<void>(`${this.apiUrl}/experiments/${experimentId}/resume`, {});
  }

  // Export best config
  exportBestConfig(experimentId: string, format: 'yaml' | 'json'): Observable<Blob> {
    return this.http.get(`${this.apiUrl}/experiments/${experimentId}/export?format=${format}`, {
      responseType: 'blob'
    });
  }
}
```

**AITunerWebSocketService** (`ai-tuner-websocket.service.ts`):
```typescript
@Injectable({providedIn: 'root'})
export class AITunerWebSocketService {
  private ws?: WebSocket;

  private iterationUpdates$ = new Subject<IterationUpdate>();
  private reasoningChunks$ = new Subject<ReasoningChunk>();
  private progressUpdates$ = new Subject<ProgressUpdate>();
  private statusUpdates$ = new Subject<StatusUpdate>();

  connect(experimentId: string): void {
    const wsUrl = `ws://localhost:8000/ws/experiments/${experimentId}`;
    this.ws = new WebSocket(wsUrl);

    this.ws.onmessage = (event) => {
      const message = JSON.parse(event.data);

      switch (message.type) {
        case 'tuner_iteration':
          this.iterationUpdates$.next(message.data);
          break;
        case 'tuner_reasoning':
          this.reasoningChunks$.next(message.data);
          break;
        case 'progress_update':
          this.progressUpdates$.next(message.data);
          break;
        case 'status_update':
          this.statusUpdates$.next(message.data);
          break;
      }
    };
  }

  disconnect(): void {
    this.ws?.close();
  }

  getIterationUpdates(): Observable<IterationUpdate> {
    return this.iterationUpdates$.asObservable();
  }

  getReasoningChunks(): Observable<ReasoningChunk> {
    return this.reasoningChunks$.asObservable();
  }

  getProgressUpdates(): Observable<ProgressUpdate> {
    return this.progressUpdates$.asObservable();
  }

  getStatusUpdates(): Observable<StatusUpdate> {
    return this.statusUpdates$.asObservable();
  }
}
```

