Subject<MetricUpdate>>();
  private reconnectIntervals = new Map<string, any>();

  constructor() {}

  /**
   * Subscribe to experiment metrics via WebSocket
   */
  subscribeToExperiment(experimentId: string): Observable<MetricUpdate> {
    // Return existing subject if already subscribed
    if (this.metricSubjects.has(experimentId)) {
      return this.metricSubjects.get(experimentId)!.asObservable();
    }

    // Create new subject
    const subject = new Subject<MetricUpdate>();
    this.metricSubjects.set(experimentId, subject);

    // Connect WebSocket
    this.connect(experimentId);

    return subject.asObservable();
  }

  /**
   * Unsubscribe from experiment metrics
   */
  unsubscribeFromExperiment(experimentId: string): void {
    // Close WebSocket
    const ws = this.connections.get(experimentId);
    if (ws) {
      ws.complete();
      this.connections.delete(experimentId);
    }

    // Complete subject
    const subject = this.metricSubjects.get(experimentId);
    if (subject) {
      subject.complete();
      this.metricSubjects.delete(experimentId);
    }

    // Clear reconnect timer
    const interval = this.reconnectIntervals.get(experimentId);
    if (interval) {
      clearInterval(interval);
      this.reconnectIntervals.delete(experimentId);
    }
  }

  private connect(experimentId: string): void {
    const wsUrl = `${environment.wsUrl}/api/v1/ws/experiments/${experimentId}/metrics`;

    const ws = webSocket<MetricUpdate>({
      url: wsUrl,
      openObserver: {
        next: () => {
          console.log(`[MetricsWS] Connected to ${experimentId}`);
          // Clear any existing reconnect timer
          const interval = this.reconnectIntervals.get(experimentId);
          if (interval) {
            clearInterval(interval);
            this.reconnectIntervals.delete(experimentId);
          }
        }
      },
      closeObserver: {
        next: () => {
          console.log(`[MetricsWS] Disconnected from ${experimentId}`);
          // Attempt reconnect after 5 seconds
          this.scheduleReconnect(experimentId);
        }
      }
    });

    this.connections.set(experimentId, ws);

    // Subscribe to messages
    ws.subscribe({
      next: (message) => {
        const subject = this.metricSubjects.get(experimentId);
        if (subject) {
          subject.next(message);
        }
      },
      error: (err) => {
        console.error(`[MetricsWS] Error for ${experimentId}:`, err);
        // Reconnect on error
        this.scheduleReconnect(experimentId);
      }
    });
  }

  private scheduleReconnect(experimentId: string): void {
    // Don't reconnect if already scheduled or unsubscribed
    if (this.reconnectIntervals.has(experimentId) || !this.metricSubjects.has(experimentId)) {
      return;
    }

    console.log(`[MetricsWS] Reconnecting to ${experimentId} in 5 seconds...`);
    const interval = setTimeout(() => {
      this.reconnectIntervals.delete(experimentId);
      this.connect(experimentId);
    }, 5000);

    this.reconnectIntervals.set(experimentId, interval);
  }

  ngOnDestroy(): void {
    // Clean up all connections
    this.connections.forEach((ws) => ws.complete());
    this.metricSubjects.forEach((subject) => subject.complete());
    this.reconnectIntervals.forEach((interval) => clearInterval(interval));
  }
}
