## 7. Integration with Supervisor

### 7.1 Modified Tick Loop

```rust
pub fn tick_once(&mut self) -> Result<SupervisorSnapshot> {
    let mut snap = SupervisorSnapshot::default();
    let now_ns = (self.now_unix_ns)();

    // === EMERGENCY HANDLING (FIRST) ===
    let emergency_frames = self.drain_topic_frames(&topics::topic_emergency())?;
    for frame in emergency_frames {
        let status = self.emergency_handler.handle_emergency(parse_emergency(&frame)?)?;
        self.emit_emergency_status(status)?;

        if status.success && matches!(
            status.emergency_type,
            EmergencyType::Abort | EmergencyType::Preempt
        ) {
            // Skip rest of tick if major intervention occurred
            return Ok(snap);
        }
    }

    // Check for pause state
    if self.emergency_handler.is_paused() {
        // Only process resume commands while paused
        let resume_frames = self.drain_topic_frames(&topics::topic_resume())?;
        for frame in resume_frames {
            self.emergency_handler.handle_resume(parse_resume(&frame)?)?;
        }
        return Ok(snap);
    }

    // === NORMAL PROCESSING (existing logic) ===
    let command_frames = self.drain_topic_frames(&topics::topic_command())?;
    // ... rest of existing tick_once logic
}
