"""Generic progress publisher for all training workflows."""

from hars_common.bus_client import BusClient
from hars_common.transports.zeromq_transport import ZeroMQTransport
from hars_common.hybrid_bus import HybridBusFrame
from pathlib import Path
import json
from typing import Optional


class ProgressPublisher:
    """Publishes training progress to event bus."""

    def __init__(self, experiment_id: str, workflow_type: str):
        self.experiment_id = experiment_id
        self.workflow_type = workflow_type

        self.bus_client = BusClient(
            component_name=f"{workflow_type}_trainer",
            config_path=Path("/app/common/config/bus.yaml"),
            transport=ZeroMQTransport(pub_endpoint='tcp://*:5555')
        )

    def publish_progress(
        self,
        current_epoch: int,
        total_epochs: int,
        metrics: dict,
        completion_percent: float,
        eta_seconds: Optional[float] = None
    ):
        """Publish training progress event."""

        payload = {
            "experiment_id": self.experiment_id,
            "workflow_type": self.workflow_type,
            "completion_percent": completion_percent,
            "current_epoch": current_epoch,
            "total_epochs": total_epochs,
            "metrics": metrics,
            "estimated_time_remaining_s": eta_seconds
        }

        header = self.bus_client.create_header(
            msg_type="progress",
            subtype="training_progress"
        )

        frame = HybridBusFrame(
            header=header,
            payload=json.dumps(payload).encode('utf-8')
        )

        self.bus_client.publish_frame("hars.execution.progress", frame)

    def publish_status(self, status: str, message: str = ""):
        """Publish status change event."""

        payload = {
            "experiment_id": self.experiment_id,
            "workflow_type": self.workflow_type,
            "status": status,  # started|running|paused|completed|failed
            "message": message
        }

        header = self.bus_client.create_header(
            msg_type="status",
            subtype="experiment_status"
        )

        frame = HybridBusFrame(
            header=header,
            payload=json.dumps(payload).encode('utf-8')
        )

        self.bus_client.publish_frame("hars.execution.status", frame)


# Integration with PyTorch Lightning callback
from pytorch_lightning.callbacks import Callback

class EventBusCallback(Callback):
    """PyTorch Lightning callback for event bus progress."""

    def __init__(self, publisher: ProgressPublisher):
        self.publisher = publisher

    def on_train_epoch_end(self, trainer, pl_module):
        """Publish progress at end of each epoch."""

        metrics = trainer.callback_metrics
        current_epoch = trainer.current_epoch
        max_epochs = trainer.max_epochs

        completion_percent = (current_epoch / max_epochs) * 100

        self.publisher.publish_progress(
            current_epoch=current_epoch,
            total_epochs=max_epochs,
            metrics={k: float(v) for k, v in metrics.items()},
            completion_percent=completion_percent
        )
