import { Injectable } from '@angular/core';
import { BehaviorSubject, Observable, Subject } from 'rxjs';

export interface ProgressUpdate {
  experiment_id: string;
  workflow_type: string;
  completion_percent: number;
  current_epoch: number;
  total_epochs: number;
  metrics: Record<string, number>;
  estimated_time_remaining_s?: number;
}

export interface TunerIteration {
  experiment_id: string;
  iteration: number;
  total_iterations: number;
  mode: 'ai' | 'hybrid' | 'bayesian';
  hyperparams: Record<string, any>;
  metrics: {
    val_loss: number;
    improvement: number;
    best_so_far: number;
  };
  confidence: number;
  ai_reasoning: string;
  suggestions: string[];
}

export interface StatusUpdate {
  experiment_id: string;
  status: string;
  message: string;
}

@Injectable({
  providedIn: 'root'
})
export class ExperimentWebSocketService {
  private ws?: WebSocket;
  private readonly reconnectInterval = 5000;

  private progressUpdates$ = new Subject<ProgressUpdate>();
  private tunerIterations$ = new Subject<TunerIteration>();
  private statusUpdates$ = new Subject<StatusUpdate>();
  private connectionStatus$ = new BehaviorSubject<'connected' | 'disconnected'>('disconnected');

  constructor() {}

  connect(experimentId: string): void {
    const wsUrl = `ws://localhost:8000/ws/experiments/${experimentId}`;

    this.ws = new WebSocket(wsUrl);

    this.ws.onopen = () => {
      console.log('WebSocket connected');
      this.connectionStatus$.next('connected');
    };

    this.ws.onmessage = (event) => {
      const message = JSON.parse(event.data);

      switch (message.type) {
        case 'progress_update':
          this.progressUpdates$.next(message.data);
          break;
        case 'tuner_iteration':
          this.tunerIterations$.next(message.data);
          break;
        case 'status_update':
          this.statusUpdates$.next(message.data);
          break;
      }
    };

    this.ws.onerror = (error) => {
      console.error('WebSocket error:', error);
    };

    this.ws.onclose = () => {
      console.log('WebSocket disconnected');
      this.connectionStatus$.next('disconnected');

      // Auto-reconnect
      setTimeout(() => this.connect(experimentId), this.reconnectInterval);
    };
  }

  disconnect(): void {
    this.ws?.close();
  }

  getProgressUpdates(): Observable<ProgressUpdate> {
    return this.progressUpdates$.asObservable();
  }

  getTunerIterations(): Observable<TunerIteration> {
    return this.tunerIterations$.asObservable();
  }

  getStatusUpdates(): Observable<StatusUpdate> {
    return this.statusUpdates$.asObservable();
  }

  getConnectionStatus(): Observable<'connected' | 'disconnected'> {
    return this.connectionStatus$.asObservable();
  }
}
