  private baseUrl = 'http://localhost:8000/api/v1';

  constructor(private http: HttpClient) {}

  listExperiments(workflowType?: string): Observable<any[]> {
    const params = workflowType ? { workflow_type: workflowType } : {};
    return this.http.get<any[]>(`${this.baseUrl}/experiments`, { params });
  }

  startVEA(name: string, configPath: string, stage: number, gpuIds: number[]): Observable<any> {
    return this.http.post(`${this.baseUrl}/experiments/vea/start`, {
      name, config_path: configPath, stage, gpu_ids: gpuIds
    });
  }

  startExpert(name: string, architecture: string, configPath: string, gpuIds: number[]): Observable<any> {
    return this.http.post(`${this.baseUrl}/experiments/expert/start`, {
      name, architecture, config_path: configPath, gpu_ids: gpuIds
    });
  }

  pauseExperiment(experimentId: string): Observable<any> {
    return this.http.post(`${this.baseUrl}/experiments/${experimentId}/pause`, {});
  }

  resumeExperiment(experimentId: string): Observable<any> {
    return this.http.post(`${this.baseUrl}/experiments/${experimentId}/resume`, {});
  }

  stopExperiment(experimentId: string): Observable<any> {
    return this.http.post(`${this.baseUrl}/experiments/${experimentId}/stop`, {});
  }
}
