export class LiveLogsViewerComponent implements OnInit, OnDestroy {
  @Input() jobId!: string;

  logs$ = new BehaviorSubject<LogEntry[]>([]);
  filteredLogs$ = new Observable<LogEntry[]>();
  searchQuery = '';
  autoScroll = true;

  private subscription?: Subscription;

  ngOnInit() {
    this.subscription = this.liveProgressService
      .subscribeToJob(this.jobId)
      .pipe(
        filter(msg => msg.type === 'log'),
        scan((acc, log) => [...acc, log], [] as LogEntry[])
      )
      .subscribe(logs => {
        this.logs$.next(logs);
        if (this.autoScroll) {
          this.scrollToBottom();
        }
      });

    this.filteredLogs$ = combineLatest([
      this.logs$,
      this.searchQuery$.pipe(debounceTime(300))
    ]).pipe(
      map(([logs, query]) =>
        logs.filter(log => log.message.includes(query))
      )
    );
  }

  ngOnDestroy() {
    this.subscription?.unsubscribe();
    this.liveProgressService.disconnect(this.jobId);
  }
}
