### 3.1 WebSocket Manager

**File**: `gui/backend/app/services/websocket_manager.py`

```python
"""WebSocket manager for real-time metric streaming."""
from fastapi import WebSocket, WebSocketDisconnect
from typing import Dict, Set, Any, Optional
import asyncio
import json
import logging
from datetime import datetime

logger = logging.getLogger(__name__)


class WebSocketManager:
    """Manages WebSocket connections for real-time metrics."""

    def __init__(self):
        # experiment_id -> Set[WebSocket]
        self.active_connections: Dict[str, Set[WebSocket]] = {}
        # Metrics buffer for each experiment
        self.metrics_buffer: Dict[str, list] = {}
        self.lock = asyncio.Lock()

    async def connect(self, websocket: WebSocket, experiment_id: str):
        """Accept WebSocket connection."""
        await websocket.accept()

        async with self.lock:
            if experiment_id not in self.active_connections:
                self.active_connections[experiment_id] = set()
            self.active_connections[experiment_id].add(websocket)

        logger.info(f"WebSocket connected for experiment: {experiment_id}")

    async def disconnect(self, websocket: WebSocket, experiment_id: str):
        """Remove WebSocket connection."""
        async with self.lock:
            if experiment_id in self.active_connections:
                self.active_connections[experiment_id].discard(websocket)
                if not self.active_connections[experiment_id]:
                    del self.active_connections[experiment_id]

        logger.info(f"WebSocket disconnected for experiment: {experiment_id}")

    async def send_metric(
        self,
        experiment_id: str,
        metric_data: Dict[str, Any]
    ):
        """Send metric update to all subscribers.

        Args:
            experiment_id: Experiment ID
            metric_data: {
                'step': int,
                'timestamp': int,  # milliseconds
                'metrics': {'loss': 0.5, 'lr': 0.0001, ...}
            }
        """
        if experiment_id not in self.active_connections:
            return

        message = json.dumps({
            'type': 'metric_update',
            'experiment_id': experiment_id,
            'data': metric_data
        })

        # Send to all connected clients
        disconnected = set()
        for websocket in self.active_connections[experiment_id]:
            try:
                await websocket.send_text(message)
            except Exception as e:
                logger.error(f"Error sending to WebSocket: {e}")
                disconnected.add(websocket)

        # Clean up disconnected clients
        if disconnected:
            async with self.lock:
                self.active_connections[experiment_id] -= disconnected

    async def send_status_update(
        self,
        experiment_id: str,
        status: str,
        progress: Optional[int] = None
    ):
        """Send status update.

        Args:
            experiment_id: Experiment ID
            status: New status (running, completed, failed)
            progress: Progress percentage (0-100)
        """
        if experiment_id not in self.active_connections:
            return

        message = json.dumps({
            'type': 'status_update',
            'experiment_id': experiment_id,
            'status': status,
            'progress': progress,
            'timestamp': int(datetime.now().timestamp() * 1000)
        })

        for websocket in list(self.active_connections[experiment_id]):
            try:
                await websocket.send_text(message)
            except:
                pass

    async def heartbeat_loop(self):
        """Send periodic heartbeat to keep connections alive."""
        while True:
            await asyncio.sleep(30)  # Every 30 seconds

            for experiment_id, connections in list(self.active_connections.items()):
                message = json.dumps({'type': 'heartbeat'})

                disconnected = set()
                for websocket in connections:
                    try:
                        await websocket.send_text(message)
                    except:
                        disconnected.add(websocket)

                if disconnected:
                    async with self.lock:
                        self.active_connections[experiment_id] -= disconnected


# Global instance
ws_manager = WebSocketManager()
