"""WebSocket endpoints for real-time metrics."""
from fastapi import APIRouter, WebSocket, WebSocketDisconnect
from app.services.websocket_manager import ws_manager
import logging

logger = logging.getLogger(__name__)
router = APIRouter()


@router.websocket("/ws/experiments/{experiment_id}/metrics")
async def experiment_metrics_websocket(
    websocket: WebSocket,
    experiment_id: str
):
    """WebSocket endpoint for real-time experiment metrics.

    Protocol:
        Client -> Server:
            {"type": "subscribe", "experiment_id": "run_123"}
            {"type": "unsubscribe"}

        Server -> Client:
            {"type": "metric_update", "experiment_id": "run_123", "data": {...}}
            {"type": "status_update", "experiment_id": "run_123", "status": "running"}
            {"type": "heartbeat"}
    """
    await ws_manager.connect(websocket, experiment_id)

    try:
        while True:
            # Keep connection alive and listen for client messages
            data = await websocket.receive_text()
            # Handle client messages if needed
            logger.debug(f"Received from client: {data}")

    except WebSocketDisconnect:
        await ws_manager.disconnect(websocket, experiment_id)
    except Exception as e:
        logger.error(f"WebSocket error: {e}")
        await ws_manager.disconnect(websocket, experiment_id)
