export class AITunerMonitorComponent {
  // Signals for reactive state
  experimentId = signal<string>('');
  currentIteration = signal<number>(0);
  totalIterations = signal<number>(10);
  progressPercent = computed(() =>
    (this.currentIteration() / this.totalIterations()) * 100
  );

  bestLoss = signal<number>(Infinity);
  currentMode = signal<string>('hybrid');
  confidence = signal<number>(0);

  iterations = signal<Iteration[]>([]);
  reasoningLog = signal<ReasoningEntry[]>([]);

  status = signal<'running' | 'paused' | 'completed' | 'failed'>('running');

  // Computed values
  isRunning = computed(() => this.status() === 'running');
  isPaused = computed(() => this.status() === 'paused');
  isComplete = computed(() => this.status() === 'completed');
}
