shared ModelManager/ModelLoader singletons** from `common.model_management` for expert lifecycle:

```python
from hars_common.model_management import get_model_manager, get_model_loader

class SupervisorRuntime:
  def __init__(self, config):
    # Use shared singletons
    self.model_manager = get_model_manager()
    self.model_loader = get_model_loader()

  def get_vram_budget(self) -> int:
    """Get available VRAM for experts.

    The shared ModelLoader tracks total VRAM usage across:
    - Cortex text LLM
    - Reporter VLM
    - Planner VLM
    - Visual encoder
    - Currently loaded experts
    """
    total_vram = self.config.vram_budget_bytes
    used_vram = self.model_loader.get_vram_usage()
    headroom = self.config.vram_headroom_bytes

    return total_vram - used_vram - headroom
```

### 10.1 Expert Loading Strategy Selection

On receiving an ExecutionPlan:

```rust
fn on_plan_received(plan: ExecutionPlan) {
  let demanded_experts = plan.collect_demanded_experts();
  let total_vram = estimate_vram_requirement(demanded_experts);
  let available_vram = get_available_vram_budget();

  if total_vram <= available_vram {
    // AOT: Batch load all experts
    load_experts_aot(demanded_experts);
  } else {
    // JIT: Stream experts with double buffering
    load_experts_jit(demanded_experts, plan);
  }
}
```

### 10.2 AOT Loading Flow

```rust
fn load_experts_aot(experts: Vec<ExpertRef>) {
  for expert in experts {
    model_loader.preload(expert);  // COLD → WARM
  }

  // Parallel promotion to HOT
  for expert in experts {
    model_loader.warm_to_hot(expert);  // WARM → HOT
  }
}
```

### 10.3 JIT Loading Flow with Progress Monitoring

```rust
fn load_experts_jit(experts: Vec<ExpertRef>, plan: ExecutionPlan) {
  let mut current_idx = 0;

  // Pre-fetch first expert
  model_loader.preload(experts[current_idx]);
  model_loader.warm_to_hot(experts[current_idx]);

  for step in plan.steps {
    // Execute current expert
    let progress_callback = |progress_pct| {
      if progress_pct >= 80.0 && current_idx + 1 < experts.len() {
        // Pre-fetch next expert to WARM in background
        spawn_async {
          model_loader.preload(experts[current_idx + 1]);
        }
      }
    };

    execute_step_with_progress(step, progress_callback);

    // Swap experts for next step
    if current_idx + 1 < experts.len() {
      model_loader.hot_to_warm(experts[current_idx]);  // Release VRAM
      model_loader.warm_to_hot(experts[current_idx + 1]);  // Load next
      current_idx += 1;
    }
  }
}
```

